import{_ as i,o as t,c as o,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2015-JAN-22 -- Ceph Tech Talk: RADOS","description":"","frontmatter":{"title":"2015-JAN-22 -- Ceph Tech Talk: RADOS","date":"2015-01-23T00:00:00.000Z","updated":"2015-01-24T00:00:00.000Z","tags":["Ceph","分布式存储","Rados","CRUSH算法","高可用性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/2015-JAN-22_--_Ceph_Tech_Talk_-_RADOS.md","filePath":"posts/2015/2015-JAN-22_--_Ceph_Tech_Talk_-_RADOS.md","lastUpdated":1780459816000}'),r={name:"posts/2015/2015-JAN-22_--_Ceph_Tech_Talk_-_RADOS.md"};function p(e,l,a,n,_,g){return t(),o("div",null,[...l[0]||(l[0]=[s("<p>会议纪要</p><p>会议主题：ROS（Rados Object Storage）分布式存储系统介绍及内部架构解析</p><p>会议时间：2015年1月22日</p><p>会议地点：[请填写会议地点]</p><p>参会人员：[请填写参会人员名单]</p><p>会议内容：</p><ol><li><p><strong>ROS概述</strong></p><ul><li>ROS是Ceph分布式存储系统的一部分，提供对象存储、块存储和POSIX文件系统。</li><li>ROS遵循横向扩展、无单点故障、自管理和开源等原则。</li></ul></li><li><p><strong>ROS组件及工作原理</strong></p><ul><li><strong>rados gateway</strong>：提供S3接口，将S3请求转换为librados请求。</li><li><strong>RBD</strong>：提供块接口，由librbd处理块读取和写入操作。</li><li><strong>SEFS</strong>：提供POSIX文件系统接口，由librados处理文件数据操作。</li><li>所有服务都基于librados，由ROS管理数据存储、复制和放置。</li></ul></li><li><p><strong>librados接口</strong></p><ul><li>支持对象存储、块存储和文件系统接口。</li><li>支持部分覆盖对象、原子读写事务和用户定义的X附加器。</li><li>使用对象映射（object map）存储元数据。</li></ul></li><li><p><strong>Ceph集群组件</strong></p><ul><li><strong>OSD</strong>：负责存储数据、处理复制和恢复。</li><li><strong>Monitor</strong>：维护集群映射，处理节点添加、删除和故障。</li><li><strong>Pool</strong>：数据存储单元，具有不同的放置规则和复制级别。</li></ul></li><li><p><strong>对象放置</strong></p><ul><li>使用CRUSH算法计算对象放置位置，支持自定义放置策略。</li><li>放置组（PG）作为排序和锁定单元。</li></ul></li><li><p><strong>缓存分层</strong></p><ul><li>支持缓存分层，允许使用不同硬件和动态调整热冷数据比例。</li><li>使用librados缓存池实现缓存分层。</li></ul></li><li><p><strong>Erasure Coding</strong></p><ul><li>支持纠删码，降低存储开销。</li><li>使用纠删码插件，支持不同的纠删码算法。</li></ul></li><li><p><strong>未来工作</strong></p><ul><li>支持纠删码的乐观客户端读取。</li><li>改进缓存分层和Erasure Coding的性能。</li></ul></li></ol><p>会议结论：</p><p>本次会议介绍了ROS分布式存储系统的内部架构和工作原理，包括组件、接口、集群组件、对象放置、缓存分层和纠删码等。会议内容对理解ROS的工作原理和性能特点具有重要意义。</p><p>后续行动：</p><ul><li>将会议内容发布在YouTube和SlideShare。</li><li>在邮件列表和IRC上回答相关问题。</li></ul>",11)])])}const u=i(r,[["render",p]]);export{d as __pageData,u as default};
